-- Spec review, third pass (2026-11-07): every category template read in full.
--  1. «المقاس» was offered on 355 categories with no sizes to choose (power banks,
--     watches, guitars, notebooks…): removed there; hats, gloves, belts, costumes,
--     helmets, rain ponchos get clothing sizes and motorcycle boots / flip-flops /
--     roller skates get shoe sizes instead
--  2. padding copied from other families removed (TV specs on speakers, food specs on
--     pet beds and toothpaste, perfume categories carrying a make-up template, bag
--     straps on luggage scales, iron specs on ironing boards, power on hand tools…);
--     correct sibling templates copied where a category had none of its own
--  3. duplicate pairs in one category reduced to one (الخامة + الخامة الأساسية, two
--     dimensions fields, two age groups, two battery lives, net weight + pack size…)
--  4. remaining misspellings and unclear labels
-- Links that hold product values are never removed.

create or replace function pg_temp.unlink(p_slug text, p_codes text[]) returns void language sql as $f$
  delete from public.category_attributes ca
   using public.categories c, public.attribute_defs d
   where c.id = ca.category_id and d.id = ca.attribute_id and c.slug_en = p_slug and c.deleted_at is null
     and d.category_id is null and d.code = any(p_codes)
     and not exists (select 1 from public.product_attribute_values v join public.products p on p.id = v.product_id
                      where v.attribute_id = ca.attribute_id and p.leaf_category_id = ca.category_id);
$f$;
create or replace function pg_temp.link(p_slug text, p_codes text[]) returns void language sql as $f$
  insert into public.category_attributes (category_id, attribute_id, sort)
  select c.id, d.id, coalesce((select max(sort) from public.category_attributes x where x.category_id = c.id), 0) + o.ord
    from public.categories c
    cross join unnest(p_codes) with ordinality o(code, ord)
    join public.attribute_defs d on d.code = o.code and d.category_id is null and d.deleted_at is null
   where c.slug_en = p_slug and c.deleted_at is null
  on conflict do nothing;
$f$;
-- remove p_code from every category that also has one of p_present
create or replace function pg_temp.drop_if(p_code text, p_present text[]) returns void language sql as $f$
  delete from public.category_attributes ca
   using public.attribute_defs d
   where d.id = ca.attribute_id and d.category_id is null and d.code = p_code
     and exists (select 1 from public.category_attributes x join public.attribute_defs e on e.id = x.attribute_id
                  where x.category_id = ca.category_id and e.code = any(p_present))
     and not exists (select 1 from public.product_attribute_values v join public.products p on p.id = v.product_id
                      where v.attribute_id = ca.attribute_id and p.leaf_category_id = ca.category_id);
$f$;

