-- a separate length / width / height already says the size
delete from public.category_attributes ca using public.attribute_defs d
 where d.id = ca.attribute_id and d.code = 'dimensions_w_d_h' and d.category_id is null
   and (select count(*) from public.category_attributes x join public.attribute_defs e on e.id = x.attribute_id
         where x.category_id = ca.category_id and e.code in ('length','width','height','depth')) >= 2
   and not exists (select 1 from public.product_attribute_values v join public.products p on p.id = v.product_id
                    where v.attribute_id = ca.attribute_id and p.leaf_category_id = ca.category_id);
-- clothing never needs a parcel weight or W×D×H
delete from public.category_attributes ca using public.attribute_defs d
 where d.id = ca.attribute_id and d.category_id is null and d.code in ('weight','dimensions_w_d_h')
   and exists (select 1 from public.category_attributes x join public.attribute_defs e on e.id = x.attribute_id
                where x.category_id = ca.category_id and e.code in ('fabric_material','sleeve_length','neckline','fit'))
   and not exists (select 1 from public.product_attribute_values v join public.products p on p.id = v.product_id
                    where v.attribute_id = ca.attribute_id and p.leaf_category_id = ca.category_id);
-- «المقاس» where the category has no size chart at all
delete from public.category_attributes ca using public.attribute_defs d
 where d.id = ca.attribute_id and d.code = 'size' and d.category_id is null
   and not exists (select 1 from public.fn_size_options_for(ca.category_id))
   and not exists (select 1 from public.product_attribute_values v join public.products p on p.id = v.product_id
                    where v.attribute_id = ca.attribute_id and p.leaf_category_id = ca.category_id);
select pg_temp.drop_if('storage', array['internal_storage_capacity']);  -- «سعة التخزين» twice on copied phone templates
